# owner: platform
"""Snap span edges to a fixed step and label the result."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step != 0:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _snap(minutes: int, step: int) -> int:
    """Nearest multiple of step, halfway values go up."""
    return (minutes + step // 2) // step * step


def _duration(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{hours}h {rest}m"


# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both edges of a span to the nearest step.

    Raises ValueError for a bad step, or when the span is so
    short that both edges land on the same step.
    """
    _check_step(step)
    return Span(
        _snap(span.start, step),
        _snap(span.end, step)
    )


# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, such as 09:00-17:15 (8h 15m)."""
    _check_step(step)
    labels = []
    for span in spans:
        snapped = round_span(span, step)
        labels.append(
            f"{format_span(snapped)} ({_duration(snapped)})"
        )
    return labels

