# owner: platform
import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_span, rounded_labels


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(
            round_span(parse_span("08:53-17:11"), 15),
            parse_span("09:00-17:15")
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_span(Span(0, 65), 10), Span(0, 70)
        )

    def test_aligned_span_is_unchanged(self):
        span = parse_span("09:00-10:30")
        self.assertEqual(round_span(span, 30), span)

    def test_end_of_day_is_kept(self):
        span = parse_span("23:50-24:00")
        self.assertEqual(
            round_span(span, 10), span
        )

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:01-09:03"), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("08:58-17:14")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span_in_order(self):
        spans = [
            parse_span("13:00-14:00"),
            parse_span("09:07-09:52")
        ]
        self.assertEqual(
            rounded_labels(spans, 5),
            [
                "13:00-14:00 (1h 0m)",
                "09:05-09:50 (0h 45m)"
            ]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [parse_span("09:00-10:00")]
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels(spans, step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        spans = [parse_span("09:00-10:00")]
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(
                    len(rounded_labels(spans, step)), 1
                )


if __name__ == "__main__":
    unittest.main()
